{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "A close N-methylpiperazine heteroaromatic analogue (compound 20b) showed a rat brain-to-plasma AUCt ratio of 9.5 and was described as rapidly entering the brain, supporting CNS access for the query's scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Another N-methylpiperazine fused heteroaromatic analogue (11e) easily crossed the BBB after systemic administration with a brain/plasma ratio of 17.5, indicating strong CNS distribution for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Trifluoperazine, which shares the N-methylpiperazine and tricyclic aromatic features, is transported across the BBB by passive diffusion with log BB 1.44, supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Netupitant, an N-methylpiperazine-containing molecule, was shown by PET to cross the BBB and distribute to multiple brain regions, providing direct evidence that this substituent does not prevent CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Compound 20l, another N-methylpiperazine heteroaromatic analogue, had a brain-to-plasma AUCt ratio of 4.9 and was reported to rapidly enter the brain, reinforcing the pattern of CNS penetration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Olanzapine is predicted to have meaningful CNS access. The query combines a low-TPSA, moderate-logD tricyclic core with an N-methylpiperazine group, and multiple structurally related N-methylpiperazine heteroaromatics show direct brain penetration (brain/plasma ratios 4.9–17.5, PET uptake, passive diffusion). The physicochemical prior is favorable and no contradictory evidence was identified.",
  "evidence_gaps": [
    "No direct olanzapine brain/plasma or CSF measurement is included in the supplied evidence; all supporting records are analogues with Morgan similarity ~0.24–0.30.",
    "Efflux-transporter data for the exact query are not provided, though known pharmacology indicates CNS activity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

